$(document).ready(function(){$("#processToPayment").click(function(e){e.preventDefault(),$("#processToPayment").hide();$("#couponCode").val();var a="default";0!=$("#orderType").length&&(a=$("#orderType").val());var o="default";0!=$("#app").length&&(o=$("#app").val());var r=$(".shipping-box").serializeArray();r.push({name:"type",value:"order"}),r.push({name:"action",value:"generate"}),r.push({name:"order",value:$("#orderId").val()}),r.push({name:"app",value:o}),r.push({name:"pgRequestType",value:a}),r.push({name:"paymentMode",value:$("#paymentMode").val()}),$.ajax({type:"POST",dataType:"json",data:r,success:function(e){200==e.status?window.location.href=e.url:console.log("Success : ",e),$("#processToPayment").show()},error:function(e){console.log("error : ",e),$("#processToPayment").show()}})}),$(".removeFromCart").click(function(e){e.preventDefault();var a=$(this).attr("id");$.ajax({type:"POST",dataType:"json",data:{type:"cart",action:"remove",id:a},success:function(e){200==e.status?location.reload():popUpMessage("center",e.msg,"error"),$("#product_"+a).hide()},error:function(e){console.log(e)}})})});